// Edit these settings.
// openWebuiUrl: where n8n can reach Open WebUI, without a trailing slash.
// expectedAdmins: the emails of everyone who should be an admin. Leave empty to skip that check.
// alertLevel: post to Slack for findings at this level or above: 'HIGH', 'MEDIUM' or 'LOW'.
return [{
  json: {
    openWebuiUrl: 'http://localhost:3000',
    expectedAdmins: ['admin@example.com'],
    alertLevel: 'MEDIUM',
  },
}];

// Turns the API answers into findings with a level, then decides whether to alert.
const s = $('Settings').first().json;
const versionAnswer = $('Get Open WebUI version').first().json;
const config = $('Get admin settings').first().json;
const usersAnswer = $('List users').first().json;
const osvAnswer = $input.first().json;

const RANK = { LOW: 1, MEDIUM: 2, HIGH: 3, CRITICAL: 4, ERROR: 5 };
const findings = [];
function add(level, text) {
  findings.push({ level, text });
}

const version = versionAnswer.error ? null : versionAnswer.version;
if (!version) add('ERROR', 'Open WebUI did not answer at ' + s.openWebuiUrl + '. Is it running, and can n8n reach it?');

// Advisories that affect this exact version.
if (version && !osvAnswer.error) {
  const vulns = osvAnswer.vulns || [];
  for (const v of vulns.slice(0, 10)) {
    const sev = String((v.database_specific && v.database_specific.severity) || 'MEDIUM').toUpperCase();
    const level = sev === 'MODERATE' ? 'MEDIUM' : (RANK[sev] ? sev : 'MEDIUM');
    add(level, 'Open WebUI ' + version + ' is affected by ' + v.id + ': ' + (v.summary || 'no summary') + ' https://osv.dev/vulnerability/' + v.id);
  }
  if (vulns.length > 10) add('MEDIUM', 'And ' + (vulns.length - 10) + ' more advisories. Update Open WebUI.');
}

// Admin settings. Key names changed in newer releases, so both spellings are read.
if (config.error || config.ENABLE_SIGNUP === undefined) {
  add('ERROR', 'Could not read the admin settings. Check that the API key belongs to an admin and that the Header Auth value starts with Bearer.');
} else {
  const role = config.DEFAULT_USER_ROLE;
  if (config.ENABLE_SIGNUP === true && role !== 'pending') {
    add('HIGH', 'Sign-up is open and new accounts get the ' + role + ' role at once: anyone who can reach this URL can use your models. Set the default role to pending, or turn sign-up off.');
  } else if (config.ENABLE_SIGNUP === true) {
    add('LOW', 'Sign-up is open; new accounts wait as pending until an admin approves them.');
  }
  if (String(config.JWT_EXPIRES_IN) === '-1') {
    add('MEDIUM', 'Login sessions never expire (JWT_EXPIRES_IN is -1), so a stolen token works forever. Set an expiry such as 4w.');
  }
  const apiKeys = config.ENABLE_API_KEYS !== undefined ? config.ENABLE_API_KEYS : config.ENABLE_API_KEY;
  const restricted = config.ENABLE_API_KEYS_ENDPOINT_RESTRICTIONS !== undefined ? config.ENABLE_API_KEYS_ENDPOINT_RESTRICTIONS : config.ENABLE_API_KEY_ENDPOINT_RESTRICTIONS;
  if (apiKeys === true && restricted !== true) {
    add('LOW', 'API keys have no endpoint restrictions: a leaked key carries all the rights of its owner.');
  }
  if (config.ENABLE_COMMUNITY_SHARING === true) {
    add('LOW', 'Community sharing is on: users can publish chats to openwebui.com.');
  }
}

// Accounts.
let users = null;
if (!usersAnswer.error) {
  try {
    const parsed = JSON.parse(usersAnswer.data);
    users = Array.isArray(parsed) ? parsed : (parsed.users || null);
  } catch (e) {
    users = null;
  }
}
if (users === null) {
  add('ERROR', 'Could not list users. This workflow needs Open WebUI 0.6 or newer and an admin API key.');
} else {
  const expected = (s.expectedAdmins || []).map(e => String(e).toLowerCase());
  const admins = users.filter(u => u.role === 'admin').map(u => String(u.email || u.name || u.id).toLowerCase());
  const extra = admins.filter(a => !expected.includes(a));
  if (expected.length && extra.length) add('HIGH', 'Admin accounts you did not list: ' + extra.join(', ') + '.');
  const pending = users.filter(u => u.role === 'pending');
  if (pending.length) add('LOW', pending.length + ' accounts are waiting for approval: ' + pending.map(u => u.email || u.name).join(', ') + '.');

  // Remembered only between runs of the active workflow, not manual test runs.
  const memory = $getWorkflowStaticData('global');
  const known = Array.isArray(memory.knownUserIds) ? memory.knownUserIds : null;
  if (known) {
    const fresh = users.filter(u => !known.includes(u.id));
    if (fresh.length) add('MEDIUM', 'New accounts since the last check: ' + fresh.map(u => (u.email || u.name) + ' (' + u.role + ')').join(', ') + '.');
  }
  memory.knownUserIds = users.map(u => u.id);
}

const threshold = RANK[String(s.alertLevel || 'MEDIUM').toUpperCase()] || 2;
const alert = findings.some(f => RANK[f.level] >= threshold);
findings.sort((a, b) => RANK[b.level] - RANK[a.level]);

const header = '*Open WebUI check for ' + s.openWebuiUrl + '*' + (version ? ' (version ' + version + ')' : '');
const body = findings.length ? findings.map(f => '[' + f.level + '] ' + f.text).join('\n') : 'No findings.';

return [{ json: { alert, findingCount: findings.length, findings, message: header + '\n' + body } }];
